const readinessScheduledDue = `-- name: ReadinessScheduledDue :many
SELECT c.id, c.workspace_id, c.scheduled_at
FROM campaigns c
JOIN workspaces w ON w.id = c.workspace_id AND w.deleted_at IS NULL
WHERE c.deleted_at IS NULL AND c.status = 'scheduled' AND c.scheduled_at IS NOT NULL
  AND c.channel = 'email'
  AND c.scheduled_at <= $1::timestamptz
  AND NOT EXISTS (SELECT 1 FROM readiness_runs r WHERE r.campaign_id = c.id AND r.ran_at >= c.scheduled_at - $2::interval)
  -- A recurring digest checks its own issues before they start (internal/digests).
  AND NOT EXISTS (SELECT 1 FROM digest_issues di WHERE di.campaign_id = c.id AND di.mode = 'auto')
ORDER BY c.scheduled_at
`

type ReadinessScheduledDueParams struct {
	Until time.Time     `json:"until"`
	Lead  time.Duration `json:"lead"`
}

type ReadinessScheduledDueRow struct {
	ID          uuid.UUID  `json:"id"`
	WorkspaceID uuid.UUID  `json:"workspaceId"`
	ScheduledAt *time.Time `json:"scheduledAt"`
}

// Scheduled campaigns starting within the window whose latest run is
// older than the window (checks run again 15 minutes before the send).
func (q *Queries) ReadinessScheduledDue(ctx context.Context, arg ReadinessScheduledDueParams) ([]ReadinessScheduledDueRow, error) {
	rows, err := q.db.Query(ctx, readinessScheduledDue, arg.Until, arg.Lead)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReadinessScheduledDueRow{}
	for rows.Next() {
		var i ReadinessScheduledDueRow
		if err := rows.Scan(&i.ID, &i.WorkspaceID, &i.ScheduledAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

